script:
sacramento_map = {
    "Baptismo":   {"check": "baptismo",   "date": "data_do_baptismo"},
    "Eucaristia": {"check": "eucaristia", "date": "data_da_eucaristia"},
    "Crisma":     {"check": "crisma",     "date": "data_do_crisma"},
}

cfg = sacramento_map.get(doc.sacramento)

# Só corre para Eucaristia e Crisma
if cfg and doc.sacramento == "eucaristia":
    check_field = cfg["check"]
    date_field = cfg["date"]

    rows = [r for r in doc.candidatos_sacramento_table if r.catecumeno]
    updated = 0

    for row in rows:
        frappe.db.set_value("Catecumeno", row.catecumeno, {
            check_field: 1,
            date_field: doc.data_do_sacramento
        })
        updated = updated + 1  # safe_exec friendly

    frappe.msgprint(
        f"Concluído: {updated} catecúmeno(s) actualizados — {doc.sacramento} ({doc.data_do_sacramento})."
    )

frappe.ui.form.on('Inscricao', {
    fase(frm) {
        if (!frm.doc.fase) return;
        frappe.call({
            method: "portal.catequese.turma.suggest_turma",
            args: { fase: frm.doc.fase },
            callback(r) {
                if (r.message) {
                    if (!frm.doc.turma || frm.doc.turma !== r.message) {
                        frm.set_value('turma', r.message).then(() => {
                            frappe.show_alert({
                                message: `Turma sugerida: ${r.message}`,
                                indicator: 'green'
                            }, 4);
                        });
                    }
                } else {
                    frappe.show_alert({
                        message: 'Nenhuma turma disponível para esta fase.',
                        indicator: 'orange'
                    }, 4);
                }
            }
        });
    },

    data_de_nascimento(frm) {
        if (!frm.doc.data_de_nascimento) {
            frm.set_value('idade', null);
            return;
        }
        const birth = new Date(frm.doc.data_de_nascimento);
        const today = new Date();
        let age = today.getFullYear() - birth.getFullYear();
        const m = today.getMonth() - birth.getMonth();
        if (m < 0 || (m === 0 && today.getDate() < birth.getDate())) age--;
        frm.set_value('idade', age);
    }
});
